/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<bool> streamWifiState( {String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel streamWifiStateChannel =
      EventChannel('dev.flutter.pigeon.flutter_opendroneid.StreamApi.streamWifiState$instanceName', pigeonMethodCodec);
  return streamWifiStateChannel.receiveBroadcastStream().map((dynamic event) {
    return event as bool;
  });
}
    
